import { salvarCadastro, recuperarCadastro } from "./storage.js";export function configurarFormulario(app) {    const formulario = app.querySelector("form");    if (!formulario) {        return;    }    const dadosCadastro = recuperarCadastro();    if (dadosCadastro) {        document.getElementById("nome").value =            dadosCadastro.nome || "";        document.getElementById("email").value =            dadosCadastro.email || "";        document.getElementById("dataNascimento").value =            dadosCadastro.dataNascimento || "";        document.getElementById("endereco").value =            dadosCadastro.endereco || "";        document.getElementById("cidade").value =            dadosCadastro.cidade || "";        document.getElementById("estado").value =            dadosCadastro.estado || "";        document.getElementById("cpf").value =            dadosCadastro.cpf || "";        document.getElementById("telefone").value =            dadosCadastro.telefone || "";        document.getElementById("cep").value =            dadosCadastro.cep || "";        document.getElementById("motivo").value =            dadosCadastro.motivo || "";    }    function mostrarErro(campo, mensagem) {        campo.style.border = "2px solid red";        const erroExistente =            campo.nextElementSibling;        if (            erroExistente &&            erroExistente.classList.contains("mensagem-erro")        ) {            erroExistente.remove();        }        const erro =            document.createElement("small");        erro.textContent = mensagem;        erro.className = "mensagem-erro";        erro.style.color = "red";        erro.style.display = "block";        campo.insertAdjacentElement("afterend", erro);    }    formulario.addEventListener("input", function(event) {        if (event.target.matches("input, textarea")) {            event.target.style.border =                "2px solid #66BB6A";            const erro =                event.target.nextElementSibling;            if (                erro &&                erro.classList.contains("mensagem-erro")            ) {                erro.remove();            }        }        if (event.target.id === "cpf") {            let cpf =                event.target.value.replace(/\D/g, "");            cpf = cpf.substring(0, 11);            if (cpf.length > 9) {                event.target.value =                    cpf.substring(0, 3) + "." +                    cpf.substring(3, 6) + "." +                    cpf.substring(6, 9) + "-" +                    cpf.substring(9, 11);            } else if (cpf.length > 6) {                event.target.value =                    cpf.substring(0, 3) + "." +                    cpf.substring(3, 6) + "." +                    cpf.substring(6);            } else if (cpf.length > 3) {                event.target.value =                    cpf.substring(0, 3) + "." +                    cpf.substring(3);            } else {                event.target.value = cpf;            }        }        if (event.target.id === "telefone") {            let telefone =                event.target.value.replace(/\D/g, "");            telefone = telefone.substring(0, 11);            if (telefone.length > 10) {                event.target.value =                    "(" + telefone.substring(0, 2) + ") " +                    telefone.substring(2, 7) + "-" +                    telefone.substring(7, 11);            } else if (telefone.length > 6) {                event.target.value =                    "(" + telefone.substring(0, 2) + ") " +                    telefone.substring(2, 6) + "-" +                    telefone.substring(6);            } else if (telefone.length > 2) {                event.target.value =                    "(" + telefone.substring(0, 2) + ") " +                    telefone.substring(2);            } else {                event.target.value = telefone;            }        }        if (event.target.id === "cep") {            let cep =                event.target.value.replace(/\D/g, "");            cep = cep.substring(0, 8);            if (cep.length > 5) {                event.target.value =                    cep.substring(0, 5) + "-" +                    cep.substring(5, 8);            } else {                event.target.value = cep;            }        }    });    formulario.addEventListener("submit", function(event) {        event.preventDefault();        const nome =            document.getElementById("nome");        const email =            document.getElementById("email");        const dataNascimento =            document.getElementById("dataNascimento");        const endereco =            document.getElementById("endereco");        const cidade =            document.getElementById("cidade");        const estado =            document.getElementById("estado");        const cpf =            document.getElementById("cpf");        const telefone =            document.getElementById("telefone");        const cep =            document.getElementById("cep");        const motivo =            document.getElementById("motivo");        let formularioValido = true;        if (nome.value.trim() === "") {            mostrarErro(                nome,                "Informe seu nome completo."            );            formularioValido = false;        }        if (            email.value.trim() === "" ||            !email.validity.valid        ) {            mostrarErro(                email,                "Informe um e-mail válido."            );            formularioValido = false;        }        if (dataNascimento.value === "") {            mostrarErro(                dataNascimento,                "Informe sua data de nascimento."            );            formularioValido = false;        }        if (endereco.value.trim() === "") {            mostrarErro(                endereco,                "Informe seu endereço."            );            formularioValido = false;        }        if (cidade.value.trim() === "") {            mostrarErro(                cidade,                "Informe sua cidade."            );            formularioValido = false;        }        if (!/^[A-Za-z]{2}$/.test(estado.value.trim())) {            mostrarErro(                estado,                "Informe a sigla do estado, por exemplo: SP."            );            formularioValido = false;        }        if (!/^\d{3}\.\d{3}\.\d{3}-\d{2}$/.test(cpf.value)) {            mostrarErro(                cpf,                "Informe o CPF no formato 000.000.000-00."            );            formularioValido = false;        }        const telefoneNumeros =            telefone.value.replace(/\D/g, "");        if (telefoneNumeros.length !== 11) {            mostrarErro(                telefone,                "Informe um telefone com 11 números."            );            formularioValido = false;        }        if (!/^\d{5}-\d{3}$/.test(cep.value)) {            mostrarErro(                cep,                "Informe o CEP no formato 00000-000."            );            formularioValido = false;        }        if (motivo.value.trim() === "") {            mostrarErro(                motivo,                "Informe por que deseja ser voluntário."            );            formularioValido = false;        }        if (formularioValido) {            const dadosCadastro = {                nome: nome.value,                email: email.value,                dataNascimento: dataNascimento.value,                endereco: endereco.value,                cidade: cidade.value,                estado: estado.value.toUpperCase(),                cpf: cpf.value,                telefone: telefone.value,                cep: cep.value,                motivo: motivo.value            };            salvarCadastro(dadosCadastro);            alert(                "Cadastro preenchido com sucesso!"            );        } else {            alert(                "Por favor, preencha corretamente todos os campos."            );        }    });}